command:
$ErrorActionPreference='Stop'
$taskRoot='C:\Users\ikuto\projects\conway-99-graph'
Set-Location -LiteralPath $taskRoot
$taskPlanPath='acceleration/results/20261003_registrar_v16_registration_prospective02/plan.json'
if((Get-FileHash -Algorithm SHA256 -LiteralPath $taskPlanPath).Hash.ToLower() -ne 'fd82aedc9cc9aa96ab25a896a1962142bb12612c7d831d0a25cbf96fd821fb80'){throw 'PLAN_HASH'}
$taskPlan=Get-Content -Raw -LiteralPath $taskPlanPath|ConvertFrom-Json
$taskPins=[ordered]@{}
function Add-Pins($map){foreach($row in $map.PSObject.Properties){if($taskPins.Contains($row.Name) -and $taskPins[$row.Name] -ne $row.Value){throw 'PIN_CONFLICT'};$taskPins[$row.Name]=$row.Value}}
Add-Pins $taskPlan.immutable_inputs_sha256
$taskDirectCount=$taskPins.Count
foreach($binding in $taskPlan.bindings_in_required_dependency_order){if((Get-FileHash -Algorithm SHA256 -LiteralPath $binding.path).Hash.ToLower() -ne $binding.sha256){throw 'BINDING_HASH'};Add-Pins ((Get-Content -Raw -LiteralPath $binding.path|ConvertFrom-Json).inputs_sha256)}
$taskGatePath=$taskPlan.independent_engineering_gate
if((Get-FileHash -Algorithm SHA256 -LiteralPath $taskGatePath).Hash.ToLower() -ne $taskPlan.independent_engineering_gate_sha256){throw 'GATE_HASH'}
Add-Pins ((Get-Content -Raw -LiteralPath $taskGatePath|ConvertFrom-Json).inputs_sha256)
$taskActual=[ordered]@{}
foreach($name in $taskPins.Keys){$resolved=(Resolve-Path -LiteralPath $name).Path;if(-not $resolved.StartsWith($taskRoot+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'INPUT_BOUNDARY'};$identity=(Get-FileHash -Algorithm SHA256 -LiteralPath $name).Hash.ToLower();if($identity -ne $taskPins[$name]){throw ('INPUT_HASH '+$name)};$taskActual[$name]=$identity}
$taskProtected=[ordered]@{}
foreach($name in @('CLAIMS.yaml','.git/index')){$taskProtected[$name]=(Get-FileHash -Algorithm SHA256 -LiteralPath $name).Hash.ToLower();if($taskProtected[$name] -ne $taskPlan.historical_current_state_expected.$name){throw ('PROTECTED_HASH '+$name)}}
$taskHead=(& 'C:\Program Files\Git\cmd\git.exe' rev-parse HEAD).Trim();if($LASTEXITCODE -ne 0 -or $taskHead -ne $taskPlan.historical_current_state_expected.HEAD){throw 'HEAD_HASH'}
foreach($path in @('acceleration/results/20261003_wave41_registration01','acceleration/results/20261003_wave41_registration_supervision01')){if(Test-Path -LiteralPath $path){throw ('OUTPUT_EXISTS '+$path)}}
$taskObservation=Get-Content -Raw -LiteralPath acceleration/results/20261003_wave41_registration_windows_observation01.json|ConvertFrom-Json
if(-not $taskObservation.launch_admissible -or @($taskObservation.unknown_recognized_workers).Count -ne 0){throw 'WORKER_OBSERVATION'}
$taskOut='acceleration/results/20261003_wave41_registration_admission01.json';if(Test-Path -LiteralPath $taskOut){throw 'ADMISSION_EXISTS'}
$taskRecord=[ordered]@{schema='V16_EXACT_MAIN_FRESH_ADMISSION_V1';timestamp=[DateTimeOffset]::UtcNow.ToString('o');status='EXACT_PIN_AND_PROTECTED_ADMISSION_PASS';plan=$taskPlanPath;plan_sha256='fd82aedc9cc9aa96ab25a896a1962142bb12612c7d831d0a25cbf96fd821fb80';direct_plan_pins=$taskDirectCount;complete_immutable_pins=$taskActual.Count;inputs_sha256=$taskActual;historical_protected_execution_state=$taskProtected;HEAD=$taskHead;windows_observation_sha256='408e093388cedeb29d9cdc1bbc52037927d68e536ccbd8d94820ce2d535c0e54';recognized_unknown_workers=0;other_agent_ownership='ROOT authorized after Native and Structural separately reported terminal/no owned workers';mathematical_replays=0;ledger_mutations=0;index_mutations=0;scope='Read-only fresh hashes/resources/output admission for exact authorized main; no mathematical approval'}
[IO.File]::WriteAllText((Join-Path $taskRoot $taskOut),(($taskRecord|ConvertTo-Json -Depth 10)+"`n"),[Text.UTF8Encoding]::new($false))
[pscustomobject]@{status=$taskRecord.status;direct=$taskDirectCount;complete=$taskActual.Count;admission_sha256=(Get-FileHash -Algorithm SHA256 -LiteralPath $taskOut).Hash.ToLower()}|ConvertTo-Json -Compress
